import json, os

def get_reward_trajectory(path):
    ckpts = sorted([d for d in os.listdir(path) if d.startswith('checkpoint-')],
                   key=lambda x: int(x.split('-')[1]))
    latest = os.path.join(path, ckpts[-1], 'trainer_state.json')
    with open(latest) as f:
        state = json.load(f)
    log_history = state.get('log_history', [])
    data = []
    for entry in log_history:
        row = {'step': entry.get('step')}
        for k in ['reward', 'reward/mean', 'kl', 'loss', 'completion_length/mean',
                   'reward/f1_reward/mean', 'reward/ced_reward/mean', 'reward/format_reward/mean',
                   'reward/flat_nli_reward/mean', 'frac_zero_std']:
            if k in entry:
                row[k] = entry[k]
        if len(row) > 1:
            data.append(row)
    return data

runs = {
    'qlora_kl001': '/root/autodl-tmp/grpo_ced_kl001',
    'qlora_lr5e6': '/root/autodl-tmp/grpo_ced_lr5e6',
    'bf16_g8': '/root/autodl-tmp/grpo_ced_g8_bf16',
    'bf16_g4': '/root/autodl-tmp/grpo_ced_g4_bf16',
}

result = {}
for name, path in runs.items():
    if os.path.exists(path):
        try:
            result[name] = get_reward_trajectory(path)
